const raw = $input.first().json;
const body = raw.body ?? raw;

const audioBase64 = body.audioBase64 || body.audio_base64;
const mimeType = body.mimeType || body.mime_type || 'audio/webm';
const duration_sec = body.duration_sec ?? body.durationSec ?? null;
const source = body.source || 'n8n-voice';

if (!audioBase64 || typeof audioBase64 !== 'string') {
  throw new Error('Missing audioBase64 in JSON body. Use voice-recorder.html or POST { audioBase64, mimeType }');
}

const prompt = `You are LeadSpark — a real estate call assistant for Indian brokers.

Listen to this phone conversation. It may be Tamil, Tanglish, Hindi, or English.

1. Transcribe accurately (Tamil in Tamil script or romanized).
2. Write a 2-3 sentence English summary for the broker.
3. Extract lead fields.

Return ONLY JSON:
{
  "transcript": "...",
  "summary": "...",
  "language_detected": "tamil|tanglish|hindi|english|mixed",
  "fields": {
    "name": null,
    "phone": null,
    "budget_min": null,
    "budget_max": null,
    "locality": null,
    "timeline": null,
    "purpose": null,
    "bhk": null,
    "lead_score": "hot|warm|cold",
    "notes": null
  }
}

hot = phone + budget + soon timeline; warm = some intent; cold = vague.`;

return [{
  json: {
    audioBase64,
    mimeType,
    duration_sec,
    source,
    created_at: new Date().toISOString(),
    gemini_body: {
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mimeType, data: audioBase64 } },
        ],
      }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json',
      },
    },
  },
}];

const prep = $('Prepare audio for Gemini').first().json;
const gemini = $input.first().json;

let parsed = {};
try {
  const text = gemini.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const cleaned = String(text).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Gemini did not return valid JSON. Check GEMINI_API_KEY and audio length.');
}

const f = parsed.fields || {};

return [{
  json: {
    created_at: prep.created_at,
    duration_sec: prep.duration_sec,
    language_detected: parsed.language_detected || 'unknown',
    transcript: parsed.transcript || '',
    summary: parsed.summary || '',
    name: f.name ?? null,
    phone: f.phone ?? null,
    budget_min: f.budget_min ?? null,
    budget_max: f.budget_max ?? null,
    locality: f.locality ?? null,
    timeline: f.timeline ?? null,
    purpose: f.purpose ?? null,
    bhk: f.bhk ?? null,
    lead_score: f.lead_score || 'cold',
    notes: f.notes ?? null,
    source: prep.source,
  },
}];
